import{c as t,Q as f,j as a,m as i}from"./chunks/framework.DOi4mjdC.js";const u="/assets/enque-42.Kbl9mg7y.png",_=JSON.parse('{"title":"TBuf简介","description":"","frontmatter":{},"headers":[{"level":1,"title":"TBuf简介","slug":"tbuf简介"}],"relativePath":"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TBuf/TBuf简介.md","filePath":"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TBuf/TBuf简介.md"}'),r={name:"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TBuf/TBuf简介.md"};function T(n,e,p,l,s,B){return f(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="tbuf简介" tabindex="-1">TBuf简介 <a class="header-anchor" href="#tbuf简介" aria-label="Permalink to &quot;TBuf简介&quot;">​</a></h1><p>使用Ascend C编程的过程中，可能会用到一些临时变量。这些临时变量占用的内存可以使用TBuf数据结构来管理，存储位置通过模板参数来设置，可以设置为不同的<a href="./../../../../其他数据类型/TPosition.html">TPosition</a>逻辑位置。</p><p>TBuf继承自TQueBind父类，继承关系如下：</p><p><img src="'+u+'" alt=""></p><p>TBuf占用的存储空间通过TPipe进行管理，您可以通过<a href="./../TPipe/InitBuffer.html">InitBuffer</a>接口为TBuf进行内存初始化操作，之后即可通过<a href="./Get.html">Get</a>获取指定长度的Tensor参与计算。</p><p>使用<a href="./../TPipe/InitBuffer.html">InitBuffer</a>为TBuf分配内存和为队列分配内存有以下差异：</p><ul><li>为TBuf分配的内存空间只能参与计算，无法执行队列的入队出队操作。</li><li>调用一次内存初始化接口，TPipe只会为TBuf分配一块内存，为队列可以通过参数设置申请多块内存。如果要使用多个临时变量，需要定义多个TBuf数据结构，对每个TBuf数据结构分别调用<a href="./../TPipe/InitBuffer.html">InitBuffer</a>接口进行内存初始化。</li><li>TBuf获取的Tensor无需释放。</li></ul>',7)])])}const P=t(r,[["render",T]]);export{_ as __pageData,P as default};
